def main():
    m.LOG.clear()
    fe_h, fe, fe_f = m.load_file(m.FE)
    cb_h, cb, cb_f = m.load_file(m.CB)
    by = {c["id"]: c for c in fe + cb}
    # drop the cb011 edit by skipping if we left a bad one; apply all
    for cid, field, old, new in EDITS:
        if cid == "cb011":
            continue
        m.setf(by[cid], field, old, new, "abs or length")
    m.write_deck(m.FE, fe_h, fe, fe_f, m.FE_SOURCES)
    m.write_deck(m.CB, cb_h, cb, cb_f, m.CB_SOURCES)
    print("applied", len(m.LOG), "field edits on", len({a[0] for a in m.LOG}), "cards")

if __name__ == "__main__":
    main()
